import { CycleStatus, HealthFlag, PeriStatus, PregnancyStatus, SymptomLog, UserProfile } from '../types';
import { addDays, daysBetween, toISODay } from './dates';
import { buildEpisodes } from './cycle/episodes';
import { BLEEDING_FLOWS } from './logs';

/**
 * A10 — non-diagnostic health flags. Copy is fixed here (not generated by the AI);
 * the coach sees active flags but cannot remove them.
 */

interface FlagInput {
  user: UserProfile;
  logs: SymptomLog[];
  cycle: CycleStatus | null;
  pregnancy: PregnancyStatus | null;
  peri: PeriStatus | null;
  now?: Date;
}

export function computeFlags({ user, logs, cycle, pregnancy, peri, now = new Date() }: FlagInput): HealthFlag[] {
  const today = toISODay(now);
  const flags: HealthFlag[] = [];
  const recent = (days: number) => logs.filter(l => l.day <= today && l.day >= addDays(today, -days + 1));

  if (user.mode === 'pregnancy' && pregnancy) {
    if (recent(2).some(l => l.flow && l.flow !== 'none')) {
      flags.push({
        id: 'preg_bleeding', severity: 'urgent', title: 'Bleeding during pregnancy',
        body: 'Contact your midwife or doctor today. If bleeding is heavy or comes with pain, dizziness or fever, call emergency services.',
      });
    }
    if (pregnancy.week >= 28) {
      const slow = recent(2).flatMap(l => l.kickSessions ?? []).some(s => {
        const minutes = (new Date(s.end).getTime() - new Date(s.start).getTime()) / 60000;
        return s.count < 10 && minutes >= 120;
      });
      if (slow) {
        flags.push({
          id: 'reduced_movement', severity: 'urgent', title: 'Fewer than 10 movements in 2 hours',
          body: 'Call your maternity unit or provider now. Do not wait until tomorrow.',
        });
      }
    }
    if (pregnancy.gestationDays >= 287) {
      flags.push({
        id: 'post_dates', severity: 'warn', title: `You are ${pregnancy.label}`,
        body: 'Past 41 weeks your provider will usually want to see you. Check your plan with them.',
      });
    }
    return flags;
  }

  if (user.mode === 'perimenopause' && peri) {
    if (peri.daysSinceLastBleed != null && peri.stage === 'postmenopause') {
      const bledAfter = recent(30).some(l => l.flow && BLEEDING_FLOWS.has(l.flow));
      if (bledAfter) {
        flags.push({
          id: 'postmeno_bleed', severity: 'warn', title: 'Bleeding after menopause',
          body: 'Any bleeding a year or more after your last period should be checked by a clinician.',
        });
      }
    }
    return flags;
  }

  if (!cycle) return flags;
  const valid = cycle.history.filter(h => !h.suspectedMissedLog).slice(-3);
  if (valid.length >= 3 && valid.filter(h => h.length < 24).length >= 2) {
    flags.push({ id: 'cycle_short', severity: 'info', title: 'Short cycles', body: 'Two of your last three cycles were under 24 days. Worth mentioning at your next check-up.' });
  }
  if (valid.length >= 3 && valid.filter(h => h.length > 38).length >= 2) {
    flags.push({ id: 'cycle_long', severity: 'info', title: 'Long cycles', body: 'Two of your last three cycles were over 38 days. Worth mentioning at your next check-up.' });
  }
  if (cycle.confidence === 'irregular') {
    flags.push({ id: 'irregular', severity: 'info', title: 'Irregular cycles', body: 'Your cycle length varies by more than 9 days. Predictions are shown as wider ranges.' });
  }

  const episodes = buildEpisodes(logs.filter(l => l.mode !== 'pregnancy' && l.day <= today));
  const lastEp = episodes[episodes.length - 1];
  if (lastEp && lastEp.length > 8 && daysBetween(lastEp.end, today) <= 30) {
    flags.push({ id: 'period_long', severity: 'info', title: 'Long period', body: `Your last period lasted ${lastEp.length} days. Periods over 8 days are worth discussing with a clinician.` });
  }
  if (lastEp && lastEp.heavyDays >= 3 && daysBetween(lastEp.end, today) <= 30) {
    flags.push({ id: 'heavy_flow', severity: 'info', title: 'Heavy flow', body: 'You logged heavy flow on 3 or more days. If you soak a pad or tampon every hour, seek care.' });
  }
  if (episodes.some(e => !e.startsCycle && daysBetween(e.start, today) <= 45)) {
    flags.push({ id: 'intermenstrual', severity: 'info', title: 'Bleeding between periods', body: 'You logged bleeding less than 15 days after a period started. If it keeps happening, see a clinician.' });
  }
  if (lastEp && daysBetween(lastEp.end, today) >= 90) {
    flags.push({ id: 'amenorrhea', severity: 'warn', title: 'No period for 90+ days', body: 'Three months without a period (when not pregnant) should be checked by a clinician.' });
  }
  return flags;
}
